with with_dims as (select s.*, d.price, d.category from store_sales s inner join products d on s.product_id = d.id), enriched as (select s.*, p.price as product_price from with_dims s inner join products p on s.product_id = p.id), with_windows as (select id, store_id, product_id, sale_date, units, price, category, first_value(category, true) over w_grp as first_known_category, last_value(price) ignore nulls over w_hist as last_known_price from enriched window w_grp as (order by units, id rows between unbounded preceding and current row), w_hist as (partition by store_id, category order by revenue, id rows between unbounded preceding and current row)), metrics as (select id, store_id, product_id, price, first_known_category, ntile(4) over w_grp as price_bucket, row_number() over w_ordered as event_seq from with_windows where sale_date <= '2024-12-26' window w_grp as (partition by product_id order by price, id), w_ordered as (partition by product_id order by last_known_price, id)), deduped as (select id, store_id, price, first_known_category, price_bucket from metrics qualify rank() over (partition by product_id, store_id order by price_bucket desc) = 1), with_windows_store_sales as (select *, lag(price, 1) over w_recent as prev_price, row_number() over w_recent as event_seq from deduped window w_recent as (partition by store_id order by price, id)) select store_id, case when price_bucket >= 7 then 'HIGH' else 'LOW' end as price_bucket_tier, percentile_approx(price, 0.9) as price_p90, approx_percentile(price_bucket, array(0.25, 0.5, 0.75)) as price_bucket_quartiles, approx_percentile(price, array(0.25, 0.5, 0.75)) as price_quartiles, percentile_approx(price, 0.95) as price_p95, approx_percentile(event_seq, 0.9) as event_seq_p90 from with_windows_store_sales group by cube (store_id, case when price_bucket >= 7 then 'HIGH' else 'LOW' end) having percentile_approx(price, 0.9) >= 0 order by price_bucket_tier desc nulls first;
